fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64> {
    let mut result = Vec::with_capacity(indices.len());
    for (i, idx) in indices.into_iter().enumerate() {
        // idx is guaranteed to be a valid row index,
        // and each row has at least indices.len() columns.
        result.push(choices[idx as usize][i]);
    }
    result
}

